import { expect } from 'chai';
import { validateEmail } from '../../src/validator.email';

suite('Email Validation Tests', () => {
  test('validates email with @company.com domain', () => {
    const validEmail = 'test@company.com';
    expect(validateEmail(validEmail)).to.be.true;
  });
  test('rejects email without @company.com domain', () => {
    const invalidEmail = 'test@otherdomain.com';
    expect(validateEmail(invalidEmail)).to.be.false;
  });
});

import { expect } from 'chai';
import { validateEmail } from '../../src/validator.email';

suite('Email Validation Tests', () => {
  test('validates email with @company.com domain', () => {
    const validEmail = 'test@company.com';
    expect(validateEmail(validEmail)).to.be.true;
  });
  test('rejects email without @company.com domain', () => {
    const invalidEmail = 'test@otherdomain.com';
    expect(validateEmail(invalidEmail)).to.be.false;
  });
  test('rejects email missing @ symbol', () => {
    const invalidEmail = 'test@company.com';
    expect(validateEmail(invalidEmail.slice(0, -1))).to.be.false;
  });
